-- PT109-S3-Q13. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT109-S3-Q13$batch07$ AND q.stimulus=$batch07$Editorialist: Some people argue that ramps and other accommodations for people using wheelchairs are unnecessary in certain business areas because those areas are not frequented by wheelchair users. What happens, however, is that once ramps and other accommodations are installed in these business areas, people who use wheelchairs come there to shop and work.$batch07$ AND q.prompt=$batch07$Which one of the following is most strongly supported by the editorialist's statements?$batch07$ AND q.correct_choice=$batch07$E$batch07$) THEN RAISE EXCEPTION 'Question changed: PT109-S3-Q13'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT109-S3-Q13$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT109-S3-Q13'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT109-S3-Q13$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Statements$batch07$, $batch07$Some people say ramps and other accommodations aren't needed in certain business areas, because wheelchair users don't go there. But once accommodations are installed in those areas, wheelchair users come to shop and work.$batch07$), (1, $batch07$Evaluate$batch07$, $batch07$Pause and infer. If wheelchair users show up as soon as the ramps go in, the lack of ramps was keeping them away. The opponents have the cause backwards: wheelchair users don't go there *because* there are no accommodations.$batch07$), (2, $batch07$Goal$batch07$, $batch07$Some areas see no wheelchair users because they lack accommodations.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT109-S3-Q13$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$Nothing tells us how owners feel about making changes.$batch07$), ($batch07$B$batch07$, $batch07$Profits never come up.$batch07$), ($batch07$C$batch07$, $batch07$Again, the passage says nothing about profits.$batch07$), ($batch07$D$batch07$, $batch07$The passage is about "certain business areas", not most businesses.$batch07$), ($batch07$E$batch07$, $batch07$When the accommodations arrive, wheelchair users arrive. So their absence before was caused, at least in some areas, by the missing accommodations.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT109-S3-Q13$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
